/* @autogenerated */
package net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.step;

import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import jakarta.ws.rs.core.MultivaluedHashMap;
import jakarta.ws.rs.core.Response;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.StepInput;
import net.civeira.phylax.feature.oauth.authentication.infrastructure.driver.html.StepOutcome;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.webauthn.application.usecase.finishauthentication.FinishAuthenticationResult;
import net.civeira.phylax.feature.oauth.webauthn.application.usecase.finishauthentication.FinishAuthenticationUsecase;
import net.civeira.phylax.feature.oauth.webauthn.domain.exception.WebAuthnException;
import net.civeira.phylax.feature.oauth.webauthn.infrastructure.driver.WebAuthnRelyingParty;

class WebAuthnLoginStepUnitTest {
  private final FinishAuthenticationUsecase finish =
      Mockito.mock(FinishAuthenticationUsecase.class);
  private final WebAuthnRelyingParty relyingParty = Mockito.mock(WebAuthnRelyingParty.class);
  private final LoginStep loginStep = Mockito.mock(LoginStep.class);
  private final AuthRequest request = Mockito.mock(AuthRequest.class);
  private final ClientDetails client = Mockito.mock(ClientDetails.class);

  private WebAuthnLoginStep step;

  @BeforeEach
  void setUp() {
    Mockito.when(request.getTenant()).thenReturn("acme");
    Mockito.when(request.getLocale()).thenReturn(Locale.ENGLISH);
    Mockito.when(relyingParty.resolve("acme")).thenReturn(
        new WebAuthnRelyingParty.Party("idp.example.com", "acme", "https://idp.example.com"));
    step = new WebAuthnLoginStep(finish, relyingParty, loginStep);
  }

  private StepInput input(String stepName, String credential) {
    MultivaluedHashMap<String, String> form = new MultivaluedHashMap<>();
    form.putSingle("step", stepName);
    form.putSingle("challengeId", "c-1");
    form.putSingle("credential", credential);
    return StepInput.builder().request(request).clientDetails(client).challenges(Optional.empty())
        .formParams(form).build();
  }

  @Test
  @DisplayName("Other steps are not handled")
  void ignores_other_steps() {
    Assertions.assertTrue(step.process(input("mfa", "{}")).isEmpty());
    Mockito.verifyNoInteractions(finish);
  }

  @Test
  @DisplayName("A verified passkey proceeds as a two-factor sign-in of its user")
  void proceeds_with_passkey_user() {
    Mockito.when(finish.finish("c-1", "acme", Map.of("id", "cred-1"), "https://idp.example.com",
        "idp.example.com")).thenReturn(new FinishAuthenticationResult("u-1", "ana"));

    StepOutcome outcome =
        step.process(input(WebAuthnLoginStep.STEP, "{\"id\":\"cred-1\"}")).orElseThrow();

    StepOutcome.Proceed proceed = Assertions.assertInstanceOf(StepOutcome.Proceed.class, outcome);
    Assertions.assertEquals("ana", proceed.username());
    Assertions.assertEquals(List.of(AuthenticationChallenge.WEBAUTHN),
        proceed.challengesState().getCompleted());
    Assertions.assertEquals(List.of("hwk", "user", "mfa"), proceed.challengesState().provenAmr());
  }

  @Test
  @DisplayName("A rejected or malformed passkey shows the login form again")
  void shows_login_on_failure() {
    Response login = Response.ok().build();
    Mockito.when(loginStep.paintForm(Mockito.eq(request), Mockito.anyString())).thenReturn(login);
    Mockito.when(
        finish.finish(Mockito.any(), Mockito.any(), Mockito.any(), Mockito.any(), Mockito.any()))
        .thenThrow(WebAuthnException.challengeUsed());

    StepOutcome rejected =
        step.process(input(WebAuthnLoginStep.STEP, "{\"id\":\"cred-1\"}")).orElseThrow();
    StepOutcome malformed = step.process(input(WebAuthnLoginStep.STEP, "not json")).orElseThrow();
    StepOutcome missing = step.process(input(WebAuthnLoginStep.STEP, "")).orElseThrow();

    for (StepOutcome outcome : List.of(rejected, malformed, missing)) {
      Assertions.assertSame(login,
          Assertions.assertInstanceOf(StepOutcome.Render.class, outcome).response());
    }
  }
}
